    TYPE_PAREN = 47
    TYPE_PAREN_ID = 48
    TYPES = 49
    TYPES_PRIME = 50
    VAR_DEF = 51
    VOID_EXPR = 52

    # === TERMINALS ===
    AND = 53
    AS = 54
    ASSIGN = 55
    BOOL = 56
    CARET = 57
    CHAR = 58
    CHARCONST = 59
    COLON = 60
    COMMA = 61
    DO = 62
    DOT = 63
